column4:
let mut published_unit_by_unit = PublishedWhileConstructing {
    versions_published: 0,
    floor_raises: 0,
    data_units_written: BTreeMap::new(),
};
for (unit_in_file, unit_bytes) in (0_u64..).zip(file_bytes.chunks(unit_payload_bytes)) {
    let published = publish_while_constructing(
        session,
        devices,
        UserChange::WriteAtOffset {
            inode: InodeNumber(file.inode),
            offset: FileOffsetInBytes(
                unit_in_file * u64::try_from(unit_payload_bytes).expect("净荷容量装得进 u64"),
            ),
            bytes: PartialWriteBytes::new(unit_bytes).expect("一个单元的净荷不是空的"),
            write_time_seconds,
        },
    )?;
    published_unit_by_unit.versions_published += published.versions_published;
    published_unit_by_unit.floor_raises += published.floor_raises;
    for (inode, units) in published.data_units_written {
        *published_unit_by_unit.data_units_written.entry(inode).or_insert(0) += units;
    }
}
Ok(published_unit_by_unit)

